import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"TUI Screens","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/tui/screens.md","filePath":"openshield-xdp/tui/screens.md","lastUpdated":1782568991000}'),d={name:"openshield-xdp/tui/screens.md"};function r(n,e,i,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="tui-screens" tabindex="-1">TUI Screens <a class="header-anchor" href="#tui-screens" aria-label="Permalink to &quot;TUI Screens&quot;">​</a></h1><p>Detailed descriptions of all 7 TUI screens and their data sources.</p><hr><h2 id="_1-dashboard-screendashboard" tabindex="-1">1. Dashboard (<code>screenDashboard</code>) <a class="header-anchor" href="#_1-dashboard-screendashboard" aria-label="Permalink to &quot;1. Dashboard (\`screenDashboard\`)&quot;">​</a></h2><p>The landing screen — a high-level overview of the firewall&#39;s current state.</p><h3 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Section</th><th>Content</th></tr></thead><tbody><tr><td><strong>Traffic panel</strong></td><td>Current PPS, BPS, peak PPS, average PPS</td></tr><tr><td><strong>Packets panel</strong></td><td>Total/passed/dropped counters, pass% and drop%</td></tr><tr><td><strong>Mitigation panel</strong></td><td>Active ban count, suspicious IP count, new sources/s, attack state</td></tr><tr><td><strong>Protocol panel</strong></td><td>TCP/UDP/ICMP PPS with percentages, SYN PPS</td></tr><tr><td><strong>PPS chart</strong></td><td>Braille streamline chart with cur/peak/avg labels</td></tr><tr><td><strong>Panic alert</strong></td><td>Shown only when panic breaker is active — red <code>⚡ PANIC MODE</code> with bulk-drop percentage</td></tr><tr><td><strong>Drop paths</strong></td><td>Breakdown of where dropped packets went (Banned, RateDrop, PanicDrop, DNS Amp, etc.)</td></tr></tbody></table><h3 id="wide-vs-narrow" tabindex="-1">Wide vs narrow <a class="header-anchor" href="#wide-vs-narrow" aria-label="Permalink to &quot;Wide vs narrow&quot;">​</a></h3><ul><li><strong>Wide terminals (≥100 cols):</strong> Traffic, Packets, and Mitigation panels side by side; Protocol panel below</li><li><strong>Narrow terminals (&lt;100 cols):</strong> Traffic + Protocol left column, Packets + Mitigation right column</li></ul><h3 id="data-source" tabindex="-1">Data source <a class="header-anchor" href="#data-source" aria-label="Permalink to &quot;Data source&quot;">​</a></h3><p><code>Snapshot.Global</code>, <code>Snapshot.Attack</code>, <code>Snapshot.Bans</code>, <code>Snapshot.Traffic</code>, <code>Snapshot.Prof</code> (drop paths)</p><hr><h2 id="_2-traffic-screentraffic" tabindex="-1">2. Traffic (<code>screenTraffic</code>) <a class="header-anchor" href="#_2-traffic-screentraffic" aria-label="Permalink to &quot;2. Traffic (\`screenTraffic\`)&quot;">​</a></h2><p>Deep-dive into traffic metrics with live charts.</p><h3 id="layout-1" tabindex="-1">Layout <a class="header-anchor" href="#layout-1" aria-label="Permalink to &quot;Layout&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Section</th><th>Content</th></tr></thead><tbody><tr><td><strong>Live Metrics panel</strong></td><td>Current PPS, BPS, TCP PPS, UDP PPS, ICMP PPS, SYN PPS</td></tr><tr><td><strong>Peak Statistics panel</strong></td><td>Peak PPS, peak BPS, average PPS, average BPS</td></tr><tr><td><strong>PPS chart</strong></td><td>Braille streamline chart with cur/peak/avg</td></tr><tr><td><strong>BPS chart</strong></td><td>Braille streamline chart with cur/peak/avg</td></tr><tr><td><strong>Protocol Distribution</strong></td><td>TCP/UDP/ICMP/SYN with horizontal bar charts showing relative proportion</td></tr><tr><td><strong>Drop paths</strong></td><td>Drop path breakdown</td></tr></tbody></table><h3 id="protocol-bar-charts" tabindex="-1">Protocol bar charts <a class="header-anchor" href="#protocol-bar-charts" aria-label="Permalink to &quot;Protocol bar charts&quot;">​</a></h3><p>Each protocol shows a filled-bar visualization:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TCP   ████████████  85.2%  1250</span></span>
<span class="line"><span>UDP   ████          12.3%   180</span></span>
<span class="line"><span>ICMP  █              2.5%    35</span></span></code></pre></div><p>Bar width adapts to terminal width. The bar is rendered using lipgloss-colored block characters.</p><h3 id="data-source-1" tabindex="-1">Data source <a class="header-anchor" href="#data-source-1" aria-label="Permalink to &quot;Data source&quot;">​</a></h3><p><code>Snapshot.Traffic</code>, <code>Snapshot.Global</code>, <code>Snapshot.Prof</code></p><hr><h2 id="_3-attacks-screenattacks" tabindex="-1">3. Attacks (<code>screenAttacks</code>) <a class="header-anchor" href="#_3-attacks-screenattacks" aria-label="Permalink to &quot;3. Attacks (\`screenAttacks\`)&quot;">​</a></h2><p>Active attack details and top offender list.</p><h3 id="normal-state" tabindex="-1">Normal state <a class="header-anchor" href="#normal-state" aria-label="Permalink to &quot;Normal state&quot;">​</a></h3><p>When no attack is active (<code>attack.state != &quot;under_attack&quot;</code>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[OK] No active attack</span></span>
<span class="line"><span></span></span>
<span class="line"><span>All traffic is within baseline parameters.</span></span>
<span class="line"><span>The system is operating normally.</span></span></code></pre></div><h3 id="under-attack" tabindex="-1">Under attack <a class="header-anchor" href="#under-attack" aria-label="Permalink to &quot;Under attack&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>State</td><td><code>UNDER ATTACK</code> (red)</td></tr><tr><td>Type</td><td>Attack classification (SYN flood, UDP amp, etc.)</td></tr><tr><td>Duration</td><td>How long the attack has been ongoing</td></tr><tr><td>Started</td><td>UTC timestamp of attack onset</td></tr><tr><td>Current PPS/BPS</td><td>Current traffic levels vs baseline</td></tr><tr><td>Spike factor</td><td>Multiplier above baseline (e.g., 3.5×)</td></tr><tr><td>New sources/s</td><td>Rate of new IPs appearing</td></tr><tr><td>Packets dropped</td><td>Total drops during this attack</td></tr><tr><td>IPs banned</td><td>Bans triggered by this attack</td></tr></tbody></table><h3 id="top-offenders-table" tabindex="-1">Top offenders table <a class="header-anchor" href="#top-offenders-table" aria-label="Permalink to &quot;Top offenders table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td>#</td><td>Rank</td></tr><tr><td>IP</td><td>Source IP address</td></tr><tr><td>PPS</td><td>Current packets/s</td></tr><tr><td>SYN</td><td>SYN packets/s</td></tr><tr><td>Score</td><td>Cumulative suspicion score</td></tr><tr><td>Status</td><td><code>SUSPECT</code> (yellow) or <code>BANNED</code> (red)</td></tr></tbody></table><p>Paginated: <code>n</code>/<code>p</code> navigate pages. Page size adapts to terminal height (~5–20 rows).</p><h3 id="attack-timeline" tabindex="-1">Attack timeline <a class="header-anchor" href="#attack-timeline" aria-label="Permalink to &quot;Attack timeline&quot;">​</a></h3><p>Shows state transitions during the attack:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>15:04:05  normal -&gt; under_attack (spike detected)</span></span>
<span class="line"><span>15:04:10  New source flood engaged</span></span>
<span class="line"><span>15:05:30  Auto subnet ban triggered for 10.0.0.0/24</span></span></code></pre></div><h3 id="data-source-2" tabindex="-1">Data source <a class="header-anchor" href="#data-source-2" aria-label="Permalink to &quot;Data source&quot;">​</a></h3><p><code>Snapshot.Attack</code>, <code>Snapshot.TopOffenders</code>, <code>Snapshot.AttackTimeline</code></p><hr><h2 id="_4-bans-screenbans" tabindex="-1">4. Bans (<code>screenBans</code>) <a class="header-anchor" href="#_4-bans-screenbans" aria-label="Permalink to &quot;4. Bans (\`screenBans\`)&quot;">​</a></h2><p>Active ban management with search and statistics.</p><h3 id="ban-table" tabindex="-1">Ban table <a class="header-anchor" href="#ban-table" aria-label="Permalink to &quot;Ban table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td>#</td><td>Row number</td></tr><tr><td>IP</td><td>Banned IP address</td></tr><tr><td>Reason</td><td>Ban reason (e.g., &quot;PPS exceeded&quot;, &quot;TCP SYN flood&quot;)</td></tr><tr><td>Score</td><td>Suspicion score at ban time</td></tr><tr><td>Remaining</td><td>Time until ban expires (countdown) or &quot;permanent&quot;</td></tr><tr><td>Star</td><td>Repeat-offender star rating (★ to ★★★★★)</td></tr></tbody></table><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h3><p>Press <code>/</code> to enter search mode. Type an IP address or reason substring to filter. Matched count shown in header. Press <code>Esc</code> to clear.</p><h3 id="by-reason-summary" tabindex="-1">By Reason summary <a class="header-anchor" href="#by-reason-summary" aria-label="Permalink to &quot;By Reason summary&quot;">​</a></h3><p>Below the ban table, a grouped summary shows ban distribution by reason:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>By Reason</span></span>
<span class="line"><span>  PPS exceeded             12 (60.0%)</span></span>
<span class="line"><span>  TCP SYN flood             5 (25.0%)</span></span>
<span class="line"><span>  UDP amplification         3 (15.0%)</span></span></code></pre></div><h3 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h3><p><code>n</code>/<code>p</code> for next/previous page. Mouse scroll wheel also works. Page size adapts to terminal height.</p><h3 id="star-system" tabindex="-1">Star system <a class="header-anchor" href="#star-system" aria-label="Permalink to &quot;Star system&quot;">​</a></h3><p>Repeat offenders get escalating ban durations via star ratings:</p><ul><li>★ (1 star) = ban_duration × 1</li><li>★★ = ban_duration × 2</li><li>★★★ = ban_duration × 4</li><li>★★★★ = ban_duration × 8</li><li>★★★★★ = ban_duration × 16</li><li>★★★★★★ = ban_duration × 32</li></ul><p>Stars decay after <code>star_decay_seconds</code> of clean behavior.</p><h3 id="data-source-3" tabindex="-1">Data source <a class="header-anchor" href="#data-source-3" aria-label="Permalink to &quot;Data source&quot;">​</a></h3><p><code>Snapshot.Bans</code></p><hr><h2 id="_5-logs-screenlogs" tabindex="-1">5. Logs (<code>screenLogs</code>) <a class="header-anchor" href="#_5-logs-screenlogs" aria-label="Permalink to &quot;5. Logs (\`screenLogs\`)&quot;">​</a></h2><p>Combined system log and security event viewer.</p><h3 id="entry-types" tabindex="-1">Entry types <a class="header-anchor" href="#entry-types" aria-label="Permalink to &quot;Entry types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prefix</th><th>Meaning</th></tr></thead><tbody><tr><td><code>BAN_TRIGGERED</code></td><td>Red — an IP was banned</td></tr><tr><td><code>ERROR</code></td><td>Red — system errors</td></tr><tr><td><code>NEW_SOURCE_FLOOD</code></td><td>Yellow — new source flood detected</td></tr><tr><td><code>WARN</code></td><td>Yellow — warnings</td></tr><tr><td><code>INFO</code></td><td>Default — informational messages</td></tr></tbody></table><p>Each entry shows: <code>HH:MM:SS LEVEL Message</code></p><h3 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><p>Full vi-style keybindings:</p><ul><li><code>j</code>/<code>k</code> or <code>↓</code>/<code>↑</code> — scroll one line</li><li><code>PgDn</code>/<code>PgUp</code> — scroll one page</li><li><code>g</code> — jump to top</li><li><code>G</code> — jump to bottom</li><li><code>w</code> — toggle line wrapping (long lines truncated by default)</li></ul><h3 id="search-1" tabindex="-1">Search <a class="header-anchor" href="#search-1" aria-label="Permalink to &quot;Search&quot;">​</a></h3><p>Press <code>/</code> to search. Matches against both the message text and log level. <code>Esc</code> clears the filter.</p><h3 id="rendering" tabindex="-1">Rendering <a class="header-anchor" href="#rendering" aria-label="Permalink to &quot;Rendering&quot;">​</a></h3><p>Visible-window optimization: only the lines currently on screen are rendered (via <code>logOffset</code> and <code>visibleLines</code>), not the entire log buffer. This keeps render times constant regardless of total log size.</p><h3 id="data-source-4" tabindex="-1">Data source <a class="header-anchor" href="#data-source-4" aria-label="Permalink to &quot;Data source&quot;">​</a></h3><p><code>Snapshot.RecentEvents</code> + <code>Snapshot.Logs</code> — merged and sorted by timestamp</p><hr><h2 id="_6-status-screenstatus" tabindex="-1">6. Status (<code>screenStatus</code>) <a class="header-anchor" href="#_6-status-screenstatus" aria-label="Permalink to &quot;6. Status (\`screenStatus\`)&quot;">​</a></h2><p>System health, configuration, and map utilization overview.</p><h3 id="system-panel" tabindex="-1">System panel <a class="header-anchor" href="#system-panel" aria-label="Permalink to &quot;System panel&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Source</th></tr></thead><tbody><tr><td>Version</td><td><code>Snapshot.System.Version</code></td></tr><tr><td>Interface</td><td><code>Snapshot.System.Interface</code></td></tr><tr><td>XDP Mode</td><td><code>Snapshot.System.XDPMode</code></td></tr><tr><td>Kernel</td><td><code>Snapshot.System.Kernel</code> (uname)</td></tr><tr><td>Uptime</td><td><code>Snapshot.System.Uptime</code> (formatted)</td></tr></tbody></table><h3 id="health-panel" tabindex="-1">Health panel <a class="header-anchor" href="#health-panel" aria-label="Permalink to &quot;Health panel&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Badge</th><th>Condition</th></tr></thead><tbody><tr><td>Loader: healthy</td><td>Loader process is running and pushing snapshots</td></tr><tr><td>XDP Program: attached</td><td>BPF program pin exists, XDP attached to NIC</td></tr><tr><td>Telemetry: connected</td><td>Socket is receiving data</td></tr><tr><td>Event Pipe: OK</td><td>Event ring buffer not overflowing</td></tr></tbody></table><p>Badges use ● green/yellow/red indicators.</p><h3 id="statistics-panel" tabindex="-1">Statistics panel <a class="header-anchor" href="#statistics-panel" aria-label="Permalink to &quot;Statistics panel&quot;">​</a></h3><p>Total/passed/dropped counters with percentages.</p><h3 id="map-utilization" tabindex="-1">Map Utilization <a class="header-anchor" href="#map-utilization" aria-label="Permalink to &quot;Map Utilization&quot;">​</a></h3><p>Progress bars showing fill levels of each BPF map:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ip_stats   ████░░░░░░  35,201 / 100,000</span></span>
<span class="line"><span>ban        █░░░░░░░░░     247 / 50,000</span></span>
<span class="line"><span>whitelist  ░░░░░░░░░░       0 / 10,000</span></span>
<span class="line"><span>events     256KB ring buffer</span></span></code></pre></div><h3 id="data-source-5" tabindex="-1">Data source <a class="header-anchor" href="#data-source-5" aria-label="Permalink to &quot;Data source&quot;">​</a></h3><p><code>Snapshot.System</code>, <code>Snapshot.Global</code>, <code>Snapshot.Maps</code>, <code>Snapshot.Prof</code></p><hr><h2 id="_7-config-screenconfig" tabindex="-1">7. Config (<code>screenConfig</code>) <a class="header-anchor" href="#_7-config-screenconfig" aria-label="Permalink to &quot;7. Config (\`screenConfig\`)&quot;">​</a></h2><p>Live configuration browser and editor.</p><h3 id="browse-mode" tabindex="-1">Browse mode <a class="header-anchor" href="#browse-mode" aria-label="Permalink to &quot;Browse mode&quot;">​</a></h3><p>Scrollable table with columns:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Value</th><th>Range</th><th>Description</th></tr></thead></table><ul><li><code>↑</code>/<code>↓</code> or <code>j</code>/<code>k</code> — navigate fields</li><li><code>Enter</code> — edit selected field (runtime-safe only)</li><li><code>r</code> — toggle showing read-only fields</li><li><code>a</code> — preview and apply pending changes</li><li><code>d</code> — discard all pending changes</li><li><code>x</code> — revert individual field (remove pending change)</li></ul><p>Fields are organized by category: Static, Validation, Dynamic, Whitelist, Maps, System, Telemetry.</p><h3 id="edit-mode" tabindex="-1">Edit mode <a class="header-anchor" href="#edit-mode" aria-label="Permalink to &quot;Edit mode&quot;">​</a></h3><p>When editing a field:</p><ul><li>Displays current value as pre-filled input</li><li><code>Enter</code> saves and validates (range checks for int/float, true/false for bool)</li><li><code>Esc</code> cancels</li><li>Validation errors shown in red inline</li></ul><h3 id="preview-mode" tabindex="-1">Preview mode <a class="header-anchor" href="#preview-mode" aria-label="Permalink to &quot;Preview mode&quot;">​</a></h3><p>Shows all pending changes before applying:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pending Changes (y=apply, n=cancel)</span></span>
<span class="line"><span>──────────────────────────────────</span></span>
<span class="line"><span>  static.pps_threshold -&gt; 500</span></span>
<span class="line"><span>  dynamic.spike_percentage -&gt; 150</span></span></code></pre></div><h3 id="apply-flow" tabindex="-1">Apply flow <a class="header-anchor" href="#apply-flow" aria-label="Permalink to &quot;Apply flow&quot;">​</a></h3><ol><li>Changes are collected in <code>pendingChanges</code> map</li><li>Press <code>a</code> to preview</li><li>Press <code>y</code> to confirm (dialog: &quot;Apply N config change(s)?&quot;)</li><li>JSON <code>config_update</code> message sent over Unix socket to loader</li><li>Loader updates BPF config map</li><li>Success/error response displayed</li></ol><h3 id="pending-change-indicators" tabindex="-1">Pending change indicators <a class="header-anchor" href="#pending-change-indicators" aria-label="Permalink to &quot;Pending change indicators&quot;">​</a></h3><ul><li>Fields with pending changes show <code>*</code> after the value in yellow</li><li>The cursor line with pending changes is highlighted yellow</li><li>Read-only fields are dimmed and marked <code>[RO]</code></li></ul><h3 id="read-only-fields" tabindex="-1">Read-only fields <a class="header-anchor" href="#read-only-fields" aria-label="Permalink to &quot;Read-only fields&quot;">​</a></h3><p>Fields that can&#39;t be changed at runtime (require XDP reattach or map recreation):</p><ul><li><code>interface</code>, <code>xdp_mode</code></li><li><code>maps.ip_stats_max</code>, <code>maps.ban_max</code>, <code>maps.whitelist_max</code>, <code>maps.event_buffer_size</code></li><li><code>dynamic.baseline_window</code>, <code>dynamic.baseline_update_interval</code>, <code>dynamic.baseline_alpha</code></li><li><code>telemetry.poll_interval</code></li></ul><p>Toggle visibility with <code>r</code>.</p><h3 id="data-source-6" tabindex="-1">Data source <a class="header-anchor" href="#data-source-6" aria-label="Permalink to &quot;Data source&quot;">​</a></h3><p>Reads the YAML config file at <code>/etc/openshield/openshield.yaml</code> and parses it into typed fields matching the runtime <code>FieldMeta</code> metadata.</p><hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p><a href="/pingless-studios-docs/openshield-xdp/tui/shortcuts">Keyboard Shortcuts</a> · <a href="/pingless-studios-docs/openshield-xdp/tui/overview">TUI Overview</a> · <a href="/pingless-studios-docs/openshield-xdp/cli/commands">CLI Reference</a></p>`,113)])])}const b=a(d,[["render",r]]);export{u as __pageData,b as default};
